import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第十六章 不可轻视女子","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/16第十六章 不可轻视女子.md","filePath":"meditation/巴利文大藏经/16第十六章 不可轻视女子.md"}'),r={name:"meditation/巴利文大藏经/16第十六章 不可轻视女子.md"};function n(i,t,_,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第十六章-不可轻视女子" tabindex="-1">第十六章 不可轻视女子 <a class="header-anchor" href="#第十六章-不可轻视女子" aria-label="Permalink to &quot;第十六章 不可轻视女子&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应16经/茉莉经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，骄萨罗国的波斯匿王来到佛陀的住所，顶礼佛陀后，他在一旁坐下。</p><p>波斯匿王正在听佛陀说法，这个时候，有一个侍从前来拜见波斯匿王，他靠近波斯匿王的耳朵说：“陛下！祝贺您，茉莉王后，刚刚生了一位漂亮的公主。”</p><p>这个侍从刚一说完话，波斯匿王立刻就闷闷不乐、愁眉苦脸。那时，佛陀看见波斯匿王闷闷不乐、愁眉苦脸的样子，就对波斯匿王说：“大王，世间有一些女子比男子好，她们胜过很多男子，她们有智慧，她们能够受持戒律，经常做善事，不做恶事，她们恭敬的侍奉公公、婆婆，她们尊敬、孝顺双方的父母。她们对丈夫一心一意、坚贞不渝。她们生出来的孩子成为英雄，成为各方的尊主、国王，这些贤明仁慈的英雄、尊主、国王就如同贤慧的妻子能照顾好家人一样，他们也能教导和管理好一方民众，他们也能教导和管理好一个国家。”</p><p>这时，佛陀说偈言：</p><p>「人主或妇人，胜比于男子。</p><p>有智慧全戒，敬姑及事夫。</p><p>以生其子者，英雄地上主。</p><p>实如贤妻子，亦教导王国。」</p>',11)]))}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
